              ),

              const SizedBox(height: 12),
              const Text(
                'Nhấn để dừng ghi âm',
                style: TextStyle(
                  fontSize: 13,
                  color: Colors.grey,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

